# This code has been partially generated by an AI.

import argparse
import asyncio
import contextlib
import json
import socket
import sys
from asyncio import AbstractEventLoop

import keyboard
from bleak import BleakClient, BleakGATTCharacteristic, BleakScanner, BLEDevice
from keyboard import KeyboardEvent

STOP = " "
MANUAL = "manual"
AUTO = "auto"


class Keyboard:
    def __init__(self, loop: AbstractEventLoop, device_number: int, robot_prefix: str = "hebobot",
                 polling_rate: int = 100, listen_host: str = "127.0.0.1", listen_port: int = 18899,
                 start_mode: str = MANUAL, verbose_detail: bool = False):
        self._client = None
        self._loop = loop
        self._service_uuid = "19B10000-E8F2-537E-4F6C-D104768A1214"
        self._characteristic_uuid = "19B10001-E8F2-537E-4F6C-D104768A1214"
        self._polling_rate = polling_rate
        self._local_keys: list[str] = []
        self._manual_key = STOP
        self._remote_key = STOP
        self._current_key = STOP
        self._last_sent_key = ""
        self.device_number = device_number
        self.robot_prefix = robot_prefix
        self.mode = start_mode if start_mode in (MANUAL, AUTO) else MANUAL
        self._listen_host = listen_host
        self._listen_port = listen_port
        self._verbose_detail = verbose_detail
        self._sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        self._sock.bind((listen_host, listen_port))
        self._sock.settimeout(0.1)

        keyboard.hook_key("w", self._key_hook)
        keyboard.hook_key("a", self._key_hook)
        keyboard.hook_key("s", self._key_hook)
        keyboard.hook_key("d", self._key_hook)
        keyboard.hook_key("p", self._mode_hook)
        keyboard.hook_key("esc", lambda _: sys.exit(0))

    @staticmethod
    def _label(key: str) -> str:
        return "stop" if key == STOP else key

    def _set_mode(self, mode: str, source: str) -> None:
        if mode not in (MANUAL, AUTO):
            return
        changed = mode != self.mode
        self.mode = mode
        # Nach dem Umschalten wartet der Controller auf neue Eingaben der aktiven Quelle.
        self._manual_key = STOP
        self._remote_key = STOP
        self._current_key = STOP
        if changed:
            print(f"Mode -> {self.mode} ({source})")

    def _trace(self, message: str) -> None:
        if self._verbose_detail:
            print(message)

    def _mode_hook(self, event: KeyboardEvent):
        if event.event_type != keyboard.KEY_DOWN:
            return
        self._set_mode(AUTO if self.mode == MANUAL else MANUAL, "Taste p")

    def _key_hook(self, event: KeyboardEvent):
        if self.mode != MANUAL:
            return
        if event.event_type == keyboard.KEY_DOWN and event.name not in self._local_keys:
            self._local_keys.append(event.name)
            self._manual_key = event.name
        if event.event_type == keyboard.KEY_UP and event.name in self._local_keys:
            self._local_keys.remove(event.name)
            if not self._local_keys:
                self._manual_key = STOP
            elif event.name == self._manual_key:
                self._manual_key = self._local_keys[-1]

    def _device_filter(self, device: BLEDevice, _advertisement):
        if device.name is None:
            return False
        name = f"{self.robot_prefix} #{self.device_number}"
        print(f'"{name}"')
        return device.name == name

    def close(self, _event: KeyboardEvent = None):
        self._loop.call_soon(self._client.disconnect)

    @staticmethod
    def disconnect(client: BleakClient):
        print(f"Disconnected from {client.address}")

    def _apply_packet(self, data: dict):
        kind = str(data.get("type") or "")
        if kind == "mode":
            mode = str(data.get("mode") or "")
            self._set_mode(mode, "Client")
            self._trace(f"Client packet: mode={mode} seq={data.get('seq')} ts={data.get('ts_ms')}")
            return
        if kind == "stop":
            if self._remote_key != STOP:
                print("Client -> stop")
            self._remote_key = STOP
            self._current_key = STOP
            self._trace(f"Client packet: stop seq={data.get('seq')} ts={data.get('ts_ms')}")
            return
        if kind == "drive" and self.mode == AUTO:
            key = str(data.get("key") or "")
            if key in ("w", "a", "s", "d"):
                if self._remote_key != key:
                    print(f"Client -> {self._label(key)}")
                self._remote_key = key
                self._trace(f"Client packet: drive={key} seq={data.get('seq')} ts={data.get('ts_ms')}")

    async def _recv_udp(self):
        while True:
            try:
                data, _addr = await asyncio.to_thread(self._sock.recvfrom, 4096)
            except TimeoutError:
                await asyncio.sleep(0.01)
                continue
            except OSError:
                await asyncio.sleep(0.01)
                continue
            try:
                packet = json.loads(data.decode("utf-8"))
            except ValueError:
                continue
            self._apply_packet(packet)

    async def handle_keys(self, client: BleakClient, characteristic: BleakGATTCharacteristic):
        await asyncio.sleep(1 / self._polling_rate)
        self._current_key = self._manual_key if self.mode == MANUAL else self._remote_key
        if self._current_key == self._last_sent_key:
            return
        await client.write_gatt_char(
            characteristic, bytearray(self._current_key.encode("utf-8")), response=True
        )
        self._last_sent_key = self._current_key

    async def start(self):
        device = await BleakScanner.find_device_by_filter(self._device_filter)
        async with BleakClient(device, disconnected_callback=self.disconnect) as self._client:
            service = self._client.services.get_service(self._service_uuid)
            characteristic = service.get_characteristic(self._characteristic_uuid)
            print(f"Connected to client {self._client.address}")
            print(f"Mode: {self.mode} · UDP: {self._listen_host}:{self._listen_port}")
            recv = asyncio.create_task(self._recv_udp())
            try:
                while True:
                    await self.handle_keys(self._client, characteristic)
            finally:
                recv.cancel()
                with contextlib.suppress(Exception):
                    await recv


def main():
    parser = argparse.ArgumentParser(prog="load.py")
    parser.add_argument("device_number", type=int, help="Roboter-Nummer, z. B. 1 für 'hebobot #1'")
    parser.add_argument("robot_prefix", nargs="?", default="hebobot",
                        help="Namenspräfix des Roboters (Standard: hebobot)")
    parser.add_argument("--listen-host", default="127.0.0.1", help="UDP-Host für Client-Befehle")
    parser.add_argument("--listen-port", type=int, default=18899, help="UDP-Port für Client-Befehle")
    parser.add_argument("--start-mode", choices=(MANUAL, AUTO), default=MANUAL,
                        help="Startmodus des Controllers")
    parser.add_argument("--verbose-detail", action="store_true",
                        help="Zeigt zusätzliche Paketdetails (seq/ts) vom KI-Client")
    args = parser.parse_args()
    loop = asyncio.new_event_loop()
    controller = Keyboard(loop, args.device_number, args.robot_prefix, listen_host=args.listen_host,
                          listen_port=args.listen_port, start_mode=args.start_mode,
                          verbose_detail=args.verbose_detail)
    try:
        loop.run_until_complete(controller.start())
    except KeyboardInterrupt:
        print("Programm was closed")
    finally:
        loop.close()


if __name__ == "__main__":
    main()
